import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 18 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–17.
 */

// ─────────────────────── PRACTICE TEST 18 · R&W M1 (27) ──────────────────────
const T18_RW_M1: SatQuestion[] = [
  { id: "t18rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The clockmaker's apprentice was praised for her ______ hands, fitting gears no wider than a grain of rice without ever slipping.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["deft", "clumsy", "idle", "weary"], correct: 0, explanation: "Fitting tiny gears without slipping requires \"deft\" (skillful, nimble) hands. \"Clumsy\" and \"idle\" contradict the skill described, and \"weary\" describes tiredness, not precision." },
  { id: "t18rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of judges ______ reviewing the final entries before announcing a winner.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The subject is the singular collective noun \"committee,\" not the plural \"judges\" in the prepositional phrase, so the singular \"is\" is correct. The plural options misagree with the singular head noun." },
  { id: "t18rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Tardigrades, microscopic animals barely half a millimeter long, can survive boiling, freezing, and even the vacuum of space by entering a dried-out, near-dead state called cryptobiosis until conditions improve.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Tardigrades endure extreme conditions by entering a dormant survival state.", "Tardigrades can only live in warm water.", "Tardigrades grow larger in the vacuum of space.", "Tardigrades die instantly when frozen."], correct: 0, explanation: "The passage says tardigrades survive boiling, freezing, and vacuum by entering cryptobiosis, a dormant state (choice A). The other choices contradict the survival ability the text describes." },
  { id: "t18rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The reservoir had dropped to a record low. ______, the town introduced strict limits on lawn watering.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "Similarly"], correct: 1, explanation: "The watering limits are a result of the low reservoir, so the cause-and-effect transition \"Consequently\" fits. \"Nevertheless\" and \"However\" signal contrast, which the logic does not support." },
  { id: "t18rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit includes everything a beginner needs ______ brushes, paints, and a folding easel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "A colon correctly introduces the list that explains what \"everything a beginner needs\" consists of. A semicolon would require an independent clause after it, and the bare comma or no punctuation creates a run-on." },
  { id: "t18rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her field notes were so ______ that another researcher could repeat the entire experiment years later without asking a single question.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "hasty", "incomplete", "illegible"], correct: 0, explanation: "Notes detailed enough to repeat an experiment without questions are \"meticulous.\" \"Hasty,\" \"incomplete,\" and \"illegible\" all describe notes that would prevent that exact reproducibility." },
  { id: "t18rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is awarded only to applicants who have completed at least sixty volunteer hours and who major in a science field.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An applicant majoring in history with eighty volunteer hours does not qualify.", "Any applicant with sixty volunteer hours qualifies.", "Science majors automatically receive the award.", "Volunteer hours are not considered."], correct: 0, explanation: "Both conditions must be met; a history major fails the science-field requirement regardless of hours (choice A). Choices B and C ignore one of the two required conditions, and D contradicts the text." },
  { id: "t18rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum restored the mural's faded colors. ______, it repaired cracks in the plaster beneath the paint.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Additionally", "Otherwise", "Instead"], correct: 1, explanation: "Repairing the plaster is a second restoration task added to restoring the colors, so \"Additionally\" fits. The contrast and substitution transitions do not match a list of complementary actions." },
  { id: "t18rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the novel's pacing ______, with chapters that lingered for pages on a single afternoon and then leapt across whole decades.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["uneven", "steady", "predictable", "rushed"], correct: 0, explanation: "Pacing that lingers in one place and then leaps across decades is \"uneven.\" \"Steady\" and \"predictable\" are opposites of that variability, and \"rushed\" captures only the leaping half." },
  { id: "t18rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Some desert plants open their pores only at night, taking in carbon dioxide in the cool darkness and storing it so they can photosynthesize by day without losing precious water.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["These plants conserve water by gathering carbon dioxide at night.", "These plants cannot photosynthesize at all.", "These plants lose most of their water during the day.", "These plants open their pores only at noon."], correct: 0, explanation: "Opening pores at night lets the plants gather CO2 without losing daytime water (choice A). The other options contradict the water-saving strategy the passage explains." },
  { id: "t18rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the new practice schedule.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "has been"], correct: 1, explanation: "In a neither/nor construction the verb agrees with the nearer subject, the plural \"players,\" so \"are\" is correct. The singular options would only fit if the nearer noun were singular." },
  { id: "t18rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first telescope the student built barely focused. ______, the experience taught her enough optics to design a far sharper instrument the next year.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "A flawed first attempt that nonetheless taught valuable lessons is a concession, signaled by \"Still.\" \"Therefore\" implies the failure caused the learning rather than occurred despite it." },
  { id: "t18rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A bakery tracked sales: it sold 120 loaves on Friday, 200 on Saturday, and 90 on Sunday.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Sunday had the lowest sales of the three days.", "Sunday had the highest sales.", "Friday had the highest sales of the three days.", "Friday and Sunday had identical sales."], correct: 0, explanation: "90 loaves on Sunday is the smallest of the three figures, so Sunday had the lowest sales (choice A). Choice B names Sunday as highest (it is the lowest), C wrongly names Friday over Saturday's 200, and D is false since 120 ≠ 90." },
  { id: "t18rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The town built a footbridge ______ connects the two halves of the riverside park.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The relative pronoun \"that\" introduces the clause modifying \"footbridge.\" \"What\" cannot introduce a relative clause modifying a noun, and \"and it\" would create a comma-splice-style run-on." },
  { id: "t18rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Tasting the soup before serving, ______ a pinch more salt seemed necessary to the cook.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["tasting the soup before serving, a pinch more salt seemed necessary to the cook", "the cook tasted the soup before serving and decided a pinch more salt was necessary", "a pinch more salt, tasting the soup, seemed necessary", "necessary was a pinch of salt, tasting the soup before serving"], correct: 1, explanation: "The modifier \"tasting the soup\" must describe the person doing the tasting, the cook, who appears right after it only in choice B. The other versions illogically attach the tasting to \"salt.\"" },
  { id: "t18rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers propose that short midday naps improve afternoon focus because a brief rest clears built-up adenosine, a chemical that makes people feel drowsy.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Workers who napped at midday made fewer errors in the afternoon than those who did not.", "Most workers prefer coffee to naps.", "Adenosine levels rise during exercise.", "Naps longer than two hours are common."], correct: 0, explanation: "Fewer afternoon errors after napping directly supports the claim that naps improve focus (choice A). The other choices concern preferences or unrelated facts that do not test the focus claim." },
  { id: "t18rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The novelist, together with her longtime editors, ______ touring three countries this spring.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The subject is the singular \"novelist\"; the \"together with\" phrase does not change the verb's number, so \"is\" is correct. The plural verbs wrongly agree with \"editors.\"" },
  { id: "t18rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A geologist wants to stress that two separate dating methods produced the same age for the rock. ______, both the radiometric test and the layer count placed it at about ten thousand years.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Notably", "However", "Otherwise"], correct: 1, explanation: "\"Notably\" highlights the striking agreement between the two methods, which is what the geologist wants to stress. The contrast transitions misrepresent two methods that agree." },
  { id: "t18rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's tone is wryly ______: it pokes gentle fun at the very academic conventions it carefully follows.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["self-aware", "earnest", "hostile", "indifferent"], correct: 0, explanation: "Poking fun at conventions it knowingly follows is \"self-aware.\" \"Earnest\" misses the wry humor, while \"hostile\" and \"indifferent\" contradict the gentle, careful attitude described." },
  { id: "t18rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to buyers who purchase an electric vehicle assembled domestically and who trade in a gas-powered car at the time of purchase.", prompt: "Which buyer clearly qualifies for the rebate?", type: "mcq", choices: ["A buyer of a domestically assembled EV who trades in a gas car.", "A buyer of an imported EV who trades in a gas car.", "A buyer of a domestic EV who keeps their gas car.", "A buyer who purchases another gas car."], correct: 0, explanation: "Both conditions, domestic assembly and a gas-car trade-in, are satisfied only in choice A. Each other option violates one of the two requirements." },
  { id: "t18rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the lighthouse lens ______ they repainted the railing along the gallery.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["lens, and then", "lens and, then", "lens then", "lens, then"], correct: 0, explanation: "A comma plus the coordinating conjunction \"and\" properly joins the two independent clauses. \"lens, then\" is a comma splice, and the other placements misposition the comma or omit the conjunction." },
  { id: "t18rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although his lectures were famous for their ______ digressions, the professor always returned, eventually, to a single clear thesis.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meandering", "concise", "rigid", "silent"], correct: 0, explanation: "Digressions contrasted with eventually reaching a thesis are \"meandering\" (wandering). \"Concise\" and \"rigid\" contradict the wandering nature, and \"silent\" makes no sense for spoken lectures." },
  { id: "t18rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist notes that towns that built public libraries in the 1900s later showed higher rates of small-business formation, crediting the libraries' free access to commercial guides and reading rooms.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Library access to guides and meeting space encouraged new businesses.", "Libraries discouraged people from starting businesses.", "Small businesses funded the libraries directly.", "Library location had no effect on business formation."], correct: 0, explanation: "The economist credits the libraries' free guides and reading rooms for the rise in businesses (choice A). The other options reverse or deny the causal link the economist proposes." },
  { id: "t18rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ it still lacked the engineering report on the bridge.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "No comma is needed before \"because\" when the dependent clause follows the main clause. A semicolon or colon would incorrectly imply an independent clause follows." },
  { id: "t18rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new sorting machine processed twice as many packages per hour. ______, the warehouse cut its overnight shifts in half.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "Cutting shifts follows from the machine's doubled output, a cause-and-effect link signaled by \"As a result.\" The contrast and example transitions do not fit the consequence." },
  { id: "t18rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach gave ______ feedback after each drill, naming the exact footwork that needed fixing rather than offering vague praise.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "general", "evasive", "flattering"], correct: 0, explanation: "Naming the exact footwork to fix, rather than vague praise, is \"specific\" feedback. \"General\" and \"evasive\" contradict the precision, and \"flattering\" matches the vague praise being rejected." },
  { id: "t18rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A long-term study found that removing a single keystone sea-star species allowed mussels to crowd out other shellfish, which in turn drove away the fish and birds that had fed on the vanished species.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Losing one key species set off a cascade that reshaped the whole community.", "The sea star had no effect on other animals.", "Mussel populations declined after the sea star left.", "Fish and birds increased once the sea star was removed."], correct: 0, explanation: "Removing the keystone sea star triggered a cascade: mussels dominated, shellfish fell, and fish and birds left (choice A). The other choices contradict the described chain of effects." },
];

// ─────────────────────── PRACTICE TEST 18 · R&W M2 easy (27) ─────────────────
const T18_RW_M2E: SatQuestion[] = [
  { id: "t18rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The juice was too ______, so I added a little water to make it less strong.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sweet", "quiet", "tall", "early"], correct: 0, explanation: "Adding water to weaken it suggests the juice was too \"sweet\" (strong). The other adjectives do not describe a taste that water would dilute." },
  { id: "t18rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three birds ______ singing in the tall oak tree.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Three birds\" is plural, so the plural verb \"are\" is correct. The singular verbs do not agree with a plural subject." },
  { id: "t18rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bees visit many flowers to collect nectar, and as they move, they spread pollen that helps the flowers make seeds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees help flowers reproduce while collecting nectar.", "Bees never touch flowers.", "Flowers make nectar from seeds.", "Bees prevent flowers from making seeds."], correct: 0, explanation: "Bees spread pollen that helps flowers make seeds while gathering nectar (choice A). The other choices contradict the helpful role the text describes." },
  { id: "t18rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie was about to start. ______, we hurried to find our seats.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "Hurrying is the result of the movie starting, so \"So\" fits. \"However\" signals a contrast that the sentence does not contain." },
  { id: "t18rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at a small restaurant near the river.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "\"Last night\" calls for the past tense \"ate.\" The present-tense and participle forms do not fit a completed past action." },
  { id: "t18rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puppy was very ______ and ran in circles around the yard for an hour.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["energetic", "sleepy", "still", "quiet"], correct: 0, explanation: "Running in circles for an hour shows the puppy was \"energetic.\" \"Sleepy,\" \"still,\" and \"quiet\" all contradict that active behavior." },
  { id: "t18rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and produces no pollution.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is expensive.", "Walking to school causes pollution.", "Walking to school is unhealthy."], correct: 0, explanation: "The text lists three benefits of walking, so choice A captures the main idea. The other options contradict each listed advantage." },
  { id: "t18rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She read for ______ hour before going to sleep.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Hour\" begins with a silent h and a vowel sound, so the article \"an\" is correct. \"A\" is used before consonant sounds." },
  { id: "t18rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The map was so ______ that we found the trail without any trouble.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "torn", "blank"], correct: 0, explanation: "Finding the trail without trouble means the map was \"clear.\" The other adjectives describe maps that would make navigation harder." },
  { id: "t18rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ planning a trip to the mountains.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The compound subject \"my sister and I\" is plural, so \"are\" is correct. The singular verbs do not agree with two people." },
  { id: "t18rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Owls have special feathers that let them fly almost silently, helping them surprise the small animals they hunt at night.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Owls' silent flight helps them hunt.", "Owls cannot fly at all.", "Owls hunt only during the day.", "Owls' feathers make loud noises."], correct: 0, explanation: "Silent flight helps owls surprise their prey (choice A). The other options contradict the silent, nighttime hunting the text describes." },
  { id: "t18rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Heavy rain flooded the road. ______, the bus had to take a longer route.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The longer route is a result of the flooding, so \"As a result\" fits. The contrast and example transitions do not match cause and effect." },
  { id: "t18rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the class ______ a documentary about volcanoes.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["watch", "watches", "watched", "watching"], correct: 2, explanation: "\"Yesterday\" requires the past tense \"watched.\" The present-tense and participle forms do not fit a completed past event." },
  { id: "t18rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "Falling asleep quickly after a long hike shows the campers were \"tired.\" The other adjectives do not explain quickly falling asleep." },
  { id: "t18rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from 7 a.m. to 8 p.m. on weekdays but is closed on Mondays for cleaning.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Monday.", "The pool is open at midnight.", "The pool never closes.", "The pool opens at 8 p.m."], correct: 0, explanation: "The pool is closed Mondays for cleaning (choice A). The other statements contradict the stated hours and closure." },
  { id: "t18rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat curled up in ______ favorite spot by the window.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The singular possessive \"its\" matches the singular \"cat.\" \"It's\" means \"it is,\" and the plural forms do not agree with one cat." },
  { id: "t18rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Many animals migrate to find food. ______, geese fly south each fall to reach warmer feeding grounds.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Geese flying south is an example of migrating animals, so \"For example\" fits. The contrast and substitution transitions do not introduce an illustration." },
  { id: "t18rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The box was too ______ to lift, so we used a cart to move it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "small", "soft"], correct: 0, explanation: "Needing a cart to move it means the box was too \"heavy.\" \"Light\" and \"small\" would not require a cart." },
  { id: "t18rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The shelves ______ filled with books of every color.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Shelves\" is plural, so the plural verb \"are\" is correct. The singular verbs do not agree with the plural subject." },
  { id: "t18rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Ice floats on water because frozen water is less dense than liquid water, which is unusual for most substances.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Ice floats because it is less dense than liquid water.", "Ice always sinks in water.", "Ice is denser than liquid water.", "Water cannot freeze."], correct: 0, explanation: "Ice floats because frozen water is less dense (choice A). The other options directly contradict the stated reason." },
  { id: "t18rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic in the park. ______, a sudden storm sent us home early.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Planning a picnic but being sent home by a storm is a contrast, so \"However\" fits. The cause-and-effect and example transitions do not match." },
  { id: "t18rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month the band ______ to perform at the city festival.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The singular collective noun \"band\" takes \"plans,\" and the present tense fits the planned future with \"next month.\" \"Planned\" would put the event in the past." },
  { id: "t18rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new laptop is very ______; it starts up in just a few seconds.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["fast", "slow", "loud", "wide"], correct: 0, explanation: "Starting up in a few seconds means the laptop is \"fast.\" \"Slow\" is the opposite, and the other words do not describe startup speed." },
  { id: "t18rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Planting trees in cities provides shade, cleans the air, and gives birds a place to nest.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["City trees offer several benefits.", "City trees harm the air.", "City trees provide no shade.", "City trees keep birds away."], correct: 0, explanation: "Three benefits are listed, so choice A captures the main idea. Each other option contradicts a stated benefit." },
  { id: "t18rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He grabbed ______ apple from the bowl on his way out.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Apple\" begins with a vowel sound, so the article \"an\" is correct. \"A\" precedes consonant sounds." },
  { id: "t18rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were easy to follow. ______, the desk took less than an hour to assemble.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "However", "Instead", "Otherwise"], correct: 0, explanation: "Quick assembly results from the easy directions, so \"As a result\" fits. The contrast and substitution transitions do not match the consequence." },
  { id: "t18rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "A disappearing rabbit trick leaves an audience \"amazed.\" The other adjectives describe reactions that do not fit a surprising trick." },
];

// ─────────────────────── PRACTICE TEST 18 · R&W M2 hard (27) ─────────────────
const T18_RW_M2H: SatQuestion[] = [
  { id: "t18rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic's praise was so ______ that readers could not tell whether she admired the film or merely tolerated it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["tepid", "fervent", "scathing", "lavish"], correct: 0, explanation: "Praise too weak to reveal real admiration is \"tepid\" (lukewarm). \"Fervent\" and \"lavish\" describe strong enthusiasm, and \"scathing\" means harshly critical, not faint." },
  { id: "t18rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens by stating a familiar proverb, then spends its remaining pages assembling counterexamples that quietly dismantle it.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It presents a common belief and then undermines it with counterexamples.", "It proves the proverb true with evidence.", "It lists proverbs without comment.", "It repeats the same proverb throughout."], correct: 0, explanation: "Stating a proverb and then dismantling it with counterexamples is a setup-then-undermine structure (choice A). The other options misread the chapter as supportive or merely repetitive." },
  { id: "t18rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 95% of its rated output in year 1, 90% in year 5, and 60% in year 20.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined faster per year between years 5 and 20 than between years 1 and 5.", "Output increased over time.", "Output stayed exactly constant.", "The panel produced nothing by year 5."], correct: 0, explanation: "From year 1 to 5 output fell 5 points over 4 years (about 1.25 points per year); from year 5 to 20 it fell 30 points over 15 years (2 points per year), a faster per-year decline (choice A). Choices B and C contradict the falling figures, and D is false since output was still 90% at year 5." },
  { id: "t18rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The drug shrank tumors in early trials. ______, it caused liver damage severe enough to halt the study.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "A promising result followed by a serious harm is a contrast, signaled by \"However.\" \"Therefore\" and \"Accordingly\" imply the benefit caused the harm, which the logic does not support." },
  { id: "t18rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to analyze\" and \"to write\" requires the infinitive \"to present.\" The gerund and bare-verb forms break the parallel series." },
  { id: "t18rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its narrator, dwelling on his cowardice as openly as his rare moments of courage.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["flatter", "condemn", "introduce", "ignore"], correct: 0, explanation: "Dwelling on the narrator's cowardice means the memoir refuses to \"flatter\" him. \"Condemn\" and \"ignore\" reverse the balanced honesty, and \"introduce\" does not fit the contrast with courage." },
  { id: "t18rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the plague as a purely medical catastrophe, the recent study frames it as a social rupture that reshaped labor, wages, and class.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a medical view of the plague with a newer social interpretation.", "To prove the plague had no social effects.", "To summarize only the traditional account.", "To deny that the plague occurred."], correct: 0, explanation: "The \"Where the traditional … the recent …\" framing contrasts two interpretations of the plague (choice A). The other options ignore the comparison or contradict the text." },
  { id: "t18rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day crew finished the inventory ahead of schedule ______ the night crew fell two hours behind on the same task.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["schedule, the", "schedule; the", "schedule the", "schedule: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone creates a splice, no punctuation creates a run-on, and a colon does not fit two contrasting clauses." },
  { id: "t18rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the committee's report is riddled with qualifications that hedge every recommendation it makes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["decisive", "cautious", "tentative", "evasive"], correct: 0, explanation: "\"Far from\" signals an opposite: a report full of hedging qualifications is the opposite of \"decisive.\" \"Cautious,\" \"tentative,\" and \"evasive\" describe the hedging itself, not its contrary." },
  { id: "t18rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the merger will lower prices for consumers. Yet in the two years after a nearly identical merger in another market, prices there rose by 8%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that casts doubt on the supporters' claim.", "It restates the supporters' claim exactly.", "It confirms that prices always fall after mergers.", "It proposes a different merger."], correct: 0, explanation: "A comparable merger that raised prices undercuts the claim that this merger will lower them (choice A). The other options misread the sentence as agreement or an unrelated proposal." },
  { id: "t18rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe rests on three essentials ______ fresh tomatoes, good olive oil, and a generous pinch of salt.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials,", "essentials:", "essentials;", "essentials"], correct: 1, explanation: "A colon introduces the list that specifies the \"three essentials.\" A semicolon needs an independent clause, and the comma or no punctuation makes the list run on." },
  { id: "t18rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorted the clear images with near-perfect accuracy. ______, it stumbled badly on photos taken in dim light.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A success on clear images followed by a failure on dim ones is a concession, signaled by \"Nonetheless.\" \"Indeed\" and \"Likewise\" would wrongly suggest agreement between the two results." },
  { id: "t18rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, students who used the new study app scored 15% higher on recall tests but reported 25% more screen fatigue than students who studied on paper.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app improved recall scores but increased reported fatigue.", "The app improved both recall and reduced fatigue.", "The app had no measurable effect.", "Paper users scored higher on recall."], correct: 0, explanation: "App users scored 15% higher on recall but reported 25% more fatigue (choice A). The other options misstate one or both of the measured outcomes." },
  { id: "t18rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The statue that stands among the older monuments ______ to a sculptor whose later works fill the museum's main hall.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The singular subject \"statue,\" not the plural \"monuments\" in the modifying phrase, takes the singular verb \"belongs.\" The other forms either misagree or are not finite verbs." },
  { id: "t18rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The architect was admired for her ______ — for stripping each design down to the few elements a building truly needed.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["austerity", "extravagance", "indecision", "nostalgia"], correct: 0, explanation: "Stripping designs to only the necessary elements reflects \"austerity\" (severe simplicity). \"Extravagance\" is the opposite, and \"indecision\" and \"nostalgia\" are unrelated to spare design." },
  { id: "t18rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that early vaccines were crude and sometimes dangerous, then argues that the very crudeness of those efforts taught the methods that made modern vaccines remarkably safe.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the source of a later strength.", "It denies that early vaccines had any flaws.", "It claims vaccines never improved.", "It lists vaccine prices over time."], correct: 0, explanation: "The crudeness of early vaccines is reframed as the source of later safety (choice A). The other options contradict the concession or invent unrelated content." },
  { id: "t18rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for months in a small studio ______ the orchestra found the concert hall's vast acoustics startling at first.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the concert hall's vast acoustics startled the orchestra", "the orchestra found the concert hall's vast acoustics startling at first", "startling were the hall's acoustics, rehearsing for months", "it was startling, the vast acoustics of the hall"], correct: 1, explanation: "The modifier \"having rehearsed for months\" must describe the orchestra, which follows it only in choice B. The other versions illogically attach the rehearsing to the acoustics or to \"it.\"" },
  { id: "t18rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "A linguist wants to underscore that an obscure dialect preserves a sound the standard language lost centuries ago. ______, the dialect retains a hard consonant that vanished from the mainstream tongue by the 1400s.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In contrast", "Specifically", "Nevertheless", "Otherwise"], correct: 1, explanation: "The second sentence gives the precise example of the preserved sound, so \"Specifically\" fits. The contrast transitions would misrepresent an illustration as opposition." },
  { id: "t18rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The negotiator's ______ — her refusal to be rushed or rattled — let her wait out opponents who grew impatient and conceded.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["composure", "volatility", "haste", "timidity"], correct: 0, explanation: "Refusing to be rushed or rattled is \"composure.\" \"Volatility\" and \"haste\" are opposites, and \"timidity\" would not let her wait out impatient opponents." },
  { id: "t18rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The historian argues that the canal's true significance lay not in the goods it carried but in the towns that sprang up along its banks, each becoming a hub of trade and migration.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The canal mattered most for the trading towns it created along its route.", "The canal carried no goods at all.", "The canal's only value was the cargo it moved.", "The towns existed long before the canal."], correct: 0, explanation: "The historian locates the canal's significance in the trading towns it spawned, not its cargo (choice A). The other options contradict that argument directly." },
  { id: "t18rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The grant supports projects in three regions ______ the northern highlands, the central plains, and the southern coast.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["regions,", "regions:", "regions;", "regions"], correct: 1, explanation: "A colon introduces the list naming the \"three regions.\" A semicolon would need an independent clause, and the comma or no punctuation creates a run-on list." },
  { id: "t18rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The lecture was anything but ______: the speaker layered jokes, anecdotes, and surprising tangents until the hour flew by.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dull", "lively", "engaging", "amusing"], correct: 0, explanation: "\"Anything but\" signals an opposite: a lecture full of jokes and tangents is the opposite of \"dull.\" The other three options are synonyms for the lively quality described, not its contrary." },
  { id: "t18rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported that a fishing ban let cod populations recover 40% over a decade, but lobster catches in the same waters fell 15% as the recovering cod preyed on young lobsters.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The ban helped cod recover while reducing lobster catches.", "The ban harmed cod populations.", "Lobster catches rose after the ban.", "The ban had no effect on either species."], correct: 0, explanation: "Cod recovered 40% while lobster catches fell 15% due to cod predation (choice A). The other options reverse or deny the reported effects." },
  { id: "t18rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The proposal, which had been revised by every department and approved by the board, ______ now ready for a public vote.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["are", "were", "is", "have been"], correct: 2, explanation: "The singular subject \"proposal\" takes the singular verb \"is\"; the intervening clauses do not change its number. The plural verbs misagree with the singular subject." },
  { id: "t18rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The first prototype overheated within minutes. ______, its failure revealed exactly which component the engineers needed to redesign.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Yet", "Therefore", "Likewise", "Meanwhile"], correct: 0, explanation: "A failure that nonetheless produced a useful insight is a concession, signaled by \"Yet.\" \"Therefore\" would wrongly cast the overheating as a planned cause of the insight." },
  { id: "t18rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The poet's imagery is strikingly ______: a single line can evoke a smell, a sound, and a color all at once.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sensory", "abstract", "plain", "muted"], correct: 0, explanation: "Imagery that evokes smell, sound, and color is \"sensory\" (appealing to the senses). \"Abstract,\" \"plain,\" and \"muted\" all contradict that vivid, multi-sense quality." },
  { id: "t18rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The economist notes that when a city replaced its flat bus fare with a distance-based one, ridership in outer neighborhoods dropped sharply, suggesting the new fares discouraged the longest, most essential trips.", prompt: "Which choice best describes the economist's reasoning?", type: "mcq", choices: ["The fare change reduced ridership on the trips it made most expensive.", "The fare change increased outer-neighborhood ridership.", "Distance had no effect on ridership.", "Flat fares discouraged short trips."], correct: 0, explanation: "Distance-based fares raised the cost of long trips, and ridership on those longest trips dropped (choice A). The other options contradict the observed decline or its cause." },
];

// ─────────────────────── PRACTICE TEST 18 · MATH M1 (22) ─────────────────────
const T18_MATH_M1: SatQuestion[] = [
  { id: "t18m1-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 5x − 3 = 22, what is the value of x?", type: "mcq", choices: ["3", "4", "5", "6"], correct: 2, explanation: "Goal: solve for x. Add 3 to both sides: 5x = 25. Divide by 5: x = 5. The trap is stopping at 5x = 25 and reading 25, or forgetting to add 3 first." },
  { id: "t18m1-2", section: "math", domain: "Algebra", difficulty: "easy", prompt: "A taxi charges a $4 base fee plus $2 per mile. Which equation gives the total cost C for m miles?", type: "mcq", choices: ["C = 4m + 2", "C = 2m + 4", "C = 6m", "C = 2m − 4"], correct: 1, explanation: "Goal: model fixed plus per-mile cost. The $4 base is constant and the $2 applies to each mile, giving C = 2m + 4. Choice A swaps the coefficients, putting the per-mile rate on the constant." },
  { id: "t18m1-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A shirt originally priced at $40 is on sale for 25% off. What is the sale price?", type: "mcq", choices: ["$10", "$25", "$30", "$32"], correct: 2, explanation: "Goal: apply a 25% discount. 25% of $40 is 0.25 × 40 = $10 off, so the sale price is 40 − 10 = $30. The trap is reporting the $10 discount itself instead of the remaining price." },
  { id: "t18m1-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "Line ℓ passes through the points (0, 1) and (2, 7). What is the slope of line ℓ?", type: "mcq", choices: ["2", "3", "4", "6"], correct: 1, explanation: "Goal: find slope from two points. Slope = (7 − 1)/(2 − 0) = 6/2 = 3. The trap is using the rise of 6 alone (choice D) without dividing by the run of 2." },
  { id: "t18m1-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x² + 2x, what is f(3)?", type: "mcq", choices: ["9", "11", "15", "18"], correct: 2, explanation: "Goal: evaluate the function at x = 3. f(3) = 3² + 2(3) = 9 + 6 = 15. The trap is computing only 3² = 9 and forgetting the 2x term." },
  { id: "t18m1-6", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has length 9 and width 4. What is its area?", type: "mcq", choices: ["13", "26", "36", "40"], correct: 2, explanation: "Goal: find rectangle area. Area = length × width = 9 × 4 = 36. The trap is computing the perimeter 2(9 + 4) = 26 (choice B) instead of the area." },
  { id: "t18m1-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The ratio of cats to dogs at a shelter is 3 to 5. If there are 24 cats, how many dogs are there?", type: "mcq", choices: ["8", "30", "40", "45"], correct: 2, explanation: "Goal: scale a ratio. The 3 in the ratio corresponds to 24 cats, so each ratio unit is 24/3 = 8 animals. Dogs = 5 × 8 = 40. The trap is multiplying 24 by 5/3 incorrectly or using 30." },
  { id: "t18m1-8", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3(x + 2) = 2x + 11, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the linear equation. Distribute: 3x + 6 = 2x + 11. Subtract 2x: x + 6 = 11. Subtract 6: x = 5. The trap is failing to distribute the 3 across both terms in the parentheses." },
  { id: "t18m1-9", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["3", "5", "7", "10"], correct: 2, explanation: "Goal: find the sum of roots. Factoring gives (x − 2)(x − 5) = 0, so the roots are 2 and 5 and their sum is 7. Alternatively, for ax² + bx + c the sum of roots is −b/a = 7. The trap is reporting the product 10 instead of the sum." },
  { id: "t18m1-10", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A data set is 4, 8, 8, 10, 20. What is the median?", type: "mcq", choices: ["8", "10", "12", "20"], correct: 0, explanation: "Goal: find the median. The five values are already in order, so the middle value (the third) is 8. The trap is computing the mean (50/5 = 10) instead of the middle value." },
  { id: "t18m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A line is given by 2x + 3y = 12. What is its y-intercept?", type: "mcq", choices: ["2", "3", "4", "6"], correct: 2, explanation: "Goal: find the y-intercept. Set x = 0: 3y = 12, so y = 4; the y-intercept is (0, 4). The trap is setting y = 0 instead, which gives the x-intercept x = 6 (choice D)." },
  { id: "t18m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 2^x = 32, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the exponential equation. Write 32 as a power of 2: 32 = 2^5, so 2^x = 2^5 and x = 5. The trap is dividing 32 by 2 to get 16 rather than recognizing 32 as 2 to the fifth power." },
  { id: "t18m1-13", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", type: "mcq", choices: ["10", "12", "14", "48"], correct: 0, explanation: "Goal: apply the Pythagorean theorem. Hypotenuse = √(6² + 8²) = √(36 + 64) = √100 = 10. The trap is adding the legs to get 14 (choice C) instead of using squares." },
  { id: "t18m1-14", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A car travels 150 miles in 3 hours. At this rate, how many miles will it travel in 5 hours?", type: "mcq", choices: ["200", "225", "250", "300"], correct: 2, explanation: "Goal: use a constant rate. The speed is 150/3 = 50 mph, so in 5 hours the car travels 50 × 5 = 250 miles. The trap is adding 150 + 100 incorrectly or using the wrong rate." },
  { id: "t18m1-15", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x + 2y = 20 and y = 2x, what is the value of x?", type: "mcq", choices: ["2", "2.5", "4", "5"], correct: 1, explanation: "Goal: solve by substitution. Replace y with 2x: 4x + 2(2x) = 20, so 4x + 4x = 20, giving 8x = 20 and x = 2.5. The trap is forgetting to double the substituted term, which would wrongly give x = 3.33." },
  { id: "t18m1-16", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "Which expression is equivalent to (x + 3)(x − 5)?", type: "mcq", choices: ["x² − 2x − 15", "x² + 2x − 15", "x² − 2x + 15", "x² − 8x − 15"], correct: 0, explanation: "Goal: expand the product. Using FOIL: x² − 5x + 3x − 15 = x² − 2x − 15. The trap is mis-signing the middle term; the −5x and +3x combine to −2x, not +2x." },
  { id: "t18m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a class of 30 students, 18 play a sport. What percent of the class plays a sport?", type: "mcq", choices: ["40%", "50%", "60%", "72%"], correct: 2, explanation: "Goal: convert a part-to-whole to a percent. 18/30 = 0.6 = 60%. The trap is computing the non-sport fraction 12/30 = 40% (choice A) instead of the sport fraction." },
  { id: "t18m1-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has radius 5. What is its area? (Use A = πr².)", type: "mcq", choices: ["10π", "20π", "25π", "50π"], correct: 2, explanation: "Goal: find circle area. A = πr² = π(5²) = 25π. The trap is using the circumference formula 2πr = 10π (choice A) or forgetting to square the radius." },
  { id: "t18m1-19", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x − y = 7 and x + y = 5, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve the system. Add the equations to eliminate y: (3x − y) + (x + y) = 7 + 5, so 4x = 12 and x = 3. The trap is subtracting the equations instead of adding, which fails to eliminate y." },
  { id: "t18m1-20", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The function g(x) = 2x² − 3x + 1. What is g(−2)?", type: "grid", gridAnswers: ["15"], explanation: "Goal: evaluate at x = −2. g(−2) = 2(−2)² − 3(−2) + 1 = 2(4) + 6 + 1 = 8 + 6 + 1 = 15. The trap is mishandling signs: −3(−2) is +6, and (−2)² is +4, not −4." },
  { id: "t18m1-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A quantity grows by 10% each year. If it starts at 200, what is its value after 2 years?", type: "mcq", choices: ["220", "240", "242", "244"], correct: 2, explanation: "Goal: apply compound growth. After year 1: 200 × 1.10 = 220. After year 2: 220 × 1.10 = 242. The trap is adding 20% once for 240, which ignores the second year's growth on the larger base." },
  { id: "t18m1-22", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have corresponding sides in the ratio 2 to 3. If the smaller triangle has area 8, what is the area of the larger triangle?", type: "mcq", choices: ["12", "16", "18", "27"], correct: 2, explanation: "Goal: scale area by the square of the side ratio. Areas scale as (3/2)² = 9/4, so the larger area is 8 × 9/4 = 18. The trap is scaling area by the side ratio 3/2 to get 12 instead of squaring it." },
];

// ─────────────────────── PRACTICE TEST 18 · MATH M2 easy (22) ────────────────
const T18_MATH_M2E: SatQuestion[] = [
  { id: "t18m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 16, what is the value of x?", type: "mcq", choices: ["5", "6", "7", "8"], correct: 2, explanation: "Goal: solve for x. Subtract 9 from both sides: x = 16 − 9 = 7. The trap is adding instead of subtracting, which would give 25." },
  { id: "t18m2e-2", section: "math", domain: "Algebra", difficulty: "easy", prompt: "What is 20% of 150?", type: "mcq", choices: ["15", "20", "30", "45"], correct: 2, explanation: "Goal: find a percent of a number. 20% = 0.20, and 0.20 × 150 = 30. The trap is computing 10% (15) instead of 20%." },
  { id: "t18m2e-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A recipe uses 2 cups of flour for every 3 cookies. How many cups of flour are needed for 9 cookies?", type: "mcq", choices: ["4", "5", "6", "9"], correct: 2, explanation: "Goal: scale a ratio. Nine cookies is 3 times 3 cookies, so the flour triples: 2 × 3 = 6 cups. The trap is adding 2 + 3 + 9 or scaling by the wrong factor." },
  { id: "t18m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x − 4, what is y when x = 2?", type: "mcq", choices: ["1", "2", "3", "6"], correct: 1, explanation: "Goal: substitute and evaluate. y = 3(2) − 4 = 6 − 4 = 2. The trap is forgetting to subtract 4 and reporting 6 (choice D)." },
  { id: "t18m2e-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 7. What is its perimeter?", type: "mcq", choices: ["14", "21", "28", "49"], correct: 2, explanation: "Goal: find a square's perimeter. Perimeter = 4 × side = 4 × 7 = 28. The trap is computing the area 7² = 49 (choice D) instead of the perimeter." },
  { id: "t18m2e-6", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 4²?", type: "mcq", choices: ["8", "12", "16", "24"], correct: 2, explanation: "Goal: evaluate the power. 4² = 4 × 4 = 16. The trap is doubling to get 8 (choice A) rather than multiplying 4 by itself." },
  { id: "t18m2e-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "The values 5, 7, and 9 have what mean (average)?", type: "mcq", choices: ["6", "7", "8", "9"], correct: 1, explanation: "Goal: find the mean. Sum is 5 + 7 + 9 = 21, divided by 3 values gives 21/3 = 7. The trap is forgetting to divide by the number of values." },
  { id: "t18m2e-8", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x = 18, what is the value of 3x?", type: "mcq", choices: ["18", "24", "27", "36"], correct: 2, explanation: "Goal: find 3x. From 2x = 18, x = 9, so 3x = 27. The trap is reporting x = 9 alone or leaving the answer as 18." },
  { id: "t18m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "Two angles of a triangle measure 50° and 60°. What is the measure of the third angle?", type: "mcq", choices: ["60°", "70°", "80°", "110°"], correct: 1, explanation: "Goal: use the triangle angle sum. The angles total 180°, so the third is 180 − 50 − 60 = 70°. The trap is stopping at 110° (the sum of the two given angles) instead of subtracting it from 180." },
  { id: "t18m2e-10", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A bag holds 4 red and 6 blue marbles. What is the probability of drawing a red marble at random?", type: "grid", gridAnswers: ["0.4", "2/5"], explanation: "Goal: find a simple probability. There are 4 red out of 10 total marbles, so P(red) = 4/10 = 2/5 = 0.4. The trap is using 4/6 (red to blue) instead of red to total." },
  { id: "t18m2e-11", section: "math", domain: "Algebra", difficulty: "easy", prompt: "Solve for x: x/4 = 6.", type: "grid", gridAnswers: ["24"], explanation: "Goal: solve for x. Multiply both sides by 4: x = 6 × 4 = 24. The trap is dividing 6 by 4 instead of multiplying." },
  { id: "t18m2e-12", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = 5x + 1, what is f(0)?", type: "mcq", choices: ["0", "1", "5", "6"], correct: 1, explanation: "Goal: evaluate at x = 0. f(0) = 5(0) + 1 = 0 + 1 = 1. The trap is reporting 5 by ignoring that 5 × 0 = 0." },
  { id: "t18m2e-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells pens at 3 for $1.50. What is the cost of 1 pen?", type: "grid", gridAnswers: ["0.5", "0.50", "1/2"], explanation: "Goal: find unit price. Divide the total by the count: $1.50 / 3 = $0.50 per pen. The trap is multiplying instead of dividing." },
  { id: "t18m2e-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 6x − 4 = 2x + 12, what is the value of x?", type: "mcq", choices: ["2", "3", "4", "8"], correct: 2, explanation: "Goal: solve the linear equation. Subtract 2x: 4x − 4 = 12. Add 4: 4x = 16. Divide by 4: x = 4. The trap is mishandling the move of 2x across the equals sign." },
  { id: "t18m2e-15", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What are the solutions to x² = 49?", type: "mcq", choices: ["7 only", "−7 only", "7 and −7", "0 and 7"], correct: 2, explanation: "Goal: solve a square equation. Taking the square root gives x = ±7, so both 7 and −7 are solutions. The trap is reporting only the positive root 7 (choice A)." },
  { id: "t18m2e-16", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has a perimeter of 30 and a length of 9. What is its width?", type: "mcq", choices: ["3", "6", "9", "12"], correct: 1, explanation: "Goal: find width from perimeter. Perimeter = 2(length + width), so 30 = 2(9 + w), giving 15 = 9 + w and w = 6. The trap is dividing 30 by the length or forgetting to halve the perimeter first." },
  { id: "t18m2e-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A number increased by 25% becomes 50. What was the original number?", type: "mcq", choices: ["25", "37.5", "40", "45"], correct: 2, explanation: "Goal: reverse a percent increase. The new value is 1.25 times the original, so original = 50 / 1.25 = 40. The trap is subtracting 25% of 50 (giving 37.5) instead of dividing by 1.25." },
  { id: "t18m2e-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "Line ℓ has slope 2 and passes through (1, 5). What is its y-intercept?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find b in y = mx + b. Substitute the point: 5 = 2(1) + b, so b = 5 − 2 = 3. The trap is forgetting to subtract the 2(1) term before solving for b." },
  { id: "t18m2e-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If x² + 6x + 9 is written as (x + a)², what is the value of a?", type: "grid", gridAnswers: ["3"], explanation: "Goal: recognize a perfect square. x² + 6x + 9 = (x + 3)², since 2a = 6 gives a = 3 and a² = 9 confirms it. The trap is choosing a = 6 from the middle term without halving it." },
  { id: "t18m2e-20", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A line of best fit predicts y = 3x + 2. What value of y does it predict when x = 6?", type: "mcq", choices: ["18", "20", "21", "24"], correct: 1, explanation: "Goal: evaluate the model. y = 3(6) + 2 = 18 + 2 = 20. The trap is reporting 18 by forgetting to add the constant 2." },
  { id: "t18m2e-21", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A cube has edge length 3. What is its volume?", type: "mcq", choices: ["9", "18", "27", "54"], correct: 2, explanation: "Goal: find a cube's volume. Volume = edge³ = 3³ = 27. The trap is computing a face area 3² = 9 (choice A) or the surface area 54 (choice D) instead of the volume." },
  { id: "t18m2e-22", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 30, what is the value of x?", type: "mcq", choices: ["5", "6", "7", "31"], correct: 2, explanation: "Goal: solve the equation. Divide both sides by 5: x − 1 = 6, then add 1: x = 7. The trap is forgetting the −1 and reporting x = 6." },
];

